<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {Plug,Plus,RefreshCw,Square,ExternalLink,Check,KeyRound} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import {emptyMcpConnector,type McpConnector,type McpTool,type McpInvocation} from './mcp-contract'
import {saveMcpConnector,discoverMcp,prepareMcpInvocation,invokeMcp,stopMcp,saveMcpResult} from './mcp-runtime'
import Sheet from '../components/Sheet.vue'
const store=useLocal(),rows=ref<Document<McpConnector>[]>([]),runs=ref<Document<McpInvocation>[]>([]),editor=ref(false),selected=ref<Document<McpConnector>|null>(null),value=ref<McpConnector>(emptyMcpConnector()),token=ref(''),tool=ref<McpTool|null>(null),target=ref<Document<McpConnector>|null>(null),args=ref('{}'),invocation=ref<Document<McpInvocation>|null>(null),error=ref(''),busy=ref(false),testing=ref('')
let disposed=false,editorEpoch=0,toolEpoch=0,previewController:AbortController|null=null,timer:ReturnType<typeof setInterval>|null=null;const controller=new AbortController()
async function load(){const vault=store.vault;if(!vault)return;const all=await vault.list('settings');if(disposed||store.vault!==vault)return;rows.value=all.filter(row=>(row.value as {assetType?:string}).assetType==='mcp-connector') as Document<McpConnector>[];runs.value=(all.filter(row=>(row.value as {assetType?:string}).assetType==='mcp-invocation') as Document<McpInvocation>[]).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))}
async function edit(row:Document<McpConnector>|null){const vault=store.vault;if(!vault)return;const epoch=++editorEpoch;token.value='';editor.value=false;const next=row?JSON.parse(canonical(row.value)):emptyMcpConnector(),credential=row?(await vault.read<{token:string}>('mcp-auth:'+row.id))?.value.token||'':'';if(disposed||epoch!==editorEpoch||store.vault!==vault||!vault.unlocked)return;selected.value=row;value.value=next;token.value=credential;busy.value=false;editor.value=true}
function closeEditor(){editorEpoch++;editor.value=false;token.value=''}
async function save(){const vault=store.vault;if(!vault||busy.value)return;const epoch=editorEpoch,id=selected.value?.id||'mcp:'+crypto.randomUUID(),revision=selected.value?.revision||0,next=JSON.parse(canonical(value.value)),credential=token.value;busy.value=true;error.value='';try{await saveMcpConnector(vault,id,revision,next,credential);if(disposed||epoch!==editorEpoch||store.vault!==vault||!vault.unlocked)return;closeEditor();await load()}catch(e){if(!disposed&&epoch===editorEpoch)error.value=(e as Error).message}finally{if(epoch===editorEpoch||!editor.value)busy.value=false}}

async function discover(row:Document<McpConnector>){if(!store.vault||testing.value)return;testing.value=row.id;error.value='';try{await discoverMcp(store.vault,row.id,controller.signal);await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{testing.value=''}}
function closeTool(){toolEpoch++;previewController?.abort();previewController=null;tool.value=null;target.value=null;invocation.value=null;busy.value=false}
function openTool(row:Document<McpConnector>,item:McpTool){closeTool();target.value=row;tool.value=item;args.value='{}';error.value=''}
async function preview(){const vault=store.vault,row=target.value,item=tool.value,epoch=toolEpoch;if(!vault||!row||!item||busy.value)return;const control=new AbortController();previewController?.abort();previewController=control;busy.value=true;try{const prepared=await prepareMcpInvocation(vault,row.id,item.name,JSON.parse(args.value),control.signal);if(disposed||epoch!==toolEpoch||store.vault!==vault||!vault.unlocked){if(vault.unlocked)void stopMcp(vault,prepared.id).catch(()=>{});return}invocation.value=prepared;await load()}catch(e){if(!disposed&&epoch===toolEpoch&&!control.signal.aborted)error.value=(e as Error).message}finally{if(epoch===toolEpoch)busy.value=false}}
async function execute(){const vault=store.vault,row=invocation.value,epoch=toolEpoch;if(!vault||!row||busy.value||row.value.connectorId!==target.value?.id||row.value.tool.name!==tool.value?.name)return;closeTool();void invokeMcp(vault,row.id).catch(e=>{if(!disposed&&store.vault===vault&&toolEpoch===epoch+1)error.value=(e as Error).message}).finally(()=>{if(!disposed&&store.vault===vault)void load()});await load()}
function reviewRun(row:Document<McpInvocation>){closeTool();invocation.value=row;tool.value=row.value.tool;target.value=rows.value.find(item=>item.id===row.value.connectorId)||null}

async function stop(row:Document<McpInvocation>){if(!store.vault)return;try{await stopMcp(store.vault,row.id);await load()}catch(e){error.value=(e as Error).message}}
async function saveResult(row:Document<McpInvocation>){if(!store.vault)return;try{await saveMcpResult(store.vault,row.id);await load()}catch(e){error.value=(e as Error).message}}
const labels={prepared:'等待确认',calling:'正在调用',completed:'已完成',failed:'调用失败',unknown:'结果未确认',cancelled:'已停止',persistence_failed:'结果待保存'}
onMounted(()=>{void load().catch(e=>error.value=(e as Error).message);timer=setInterval(()=>void load().catch(()=>{}),1000)})
onUnmounted(()=>{disposed=true;editorEpoch++;closeTool();controller.abort();token.value='';if(timer)clearInterval(timer)})
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">TOOLS & CONNECTIONS</span><h1>MCP 工具</h1></div><button class="final-primary" @click="edit(null)"><Plus :size="18"/>连接服务</button></div><p v-if="error" class="final-error" role="alert">{{error}}</p><div v-if="!rows.length" class="final-empty"><Plug :size="36"/><h2>连接你的工具</h2><button @click="edit(null)">添加 MCP 地址</button></div><div class="final-mcp-grid"><article v-for="row in rows" :key="row.id" class="final-setting-card"><div class="final-section-title"><h2>{{row.value.name}}</h2><small>{{row.value.enabled?'已启用':'已停用'}}</small></div><p class="final-subtle final-mcp-url">{{row.value.url}}</p><div class="final-grid-actions"><button @click="edit(row)">配置与授权</button><button :disabled="!row.value.enabled||!!testing" @click="discover(row)"><RefreshCw :size="16"/>{{testing===row.id?'正在发现':'发现工具'}}</button></div><div class="final-mcp-tools"><button v-for="item in row.value.tools" :key="item.name" :disabled="!row.value.enabled||!row.value.allowedTools.includes(item.name)" @click="openTool(row,item)"><Plug :size="16"/><span>{{item.title||item.name}}<small>{{row.value.allowedTools.includes(item.name)?'已授权':'未授权'}}</small></span></button></div></article></div><div class="final-section-title" v-if="runs.length"><h2>调用记录</h2></div><article v-for="run in runs" :key="run.id" class="final-setting-card final-mcp-run"><div class="final-section-title"><strong>{{run.value.tool.title||run.value.tool.name}}</strong><small role="status">{{labels[run.value.status]}}</small></div><p v-if="run.value.error" class="final-error">{{run.value.error}}</p><details><summary>参数与来源</summary><pre>{{JSON.stringify(run.value.arguments,null,2)}}</pre><a :href="run.value.sourceUrl" target="_blank" rel="noopener noreferrer"><ExternalLink :size="14"/>{{run.value.sourceUrl}}</a></details><details v-if="run.value.result!==null"><summary>工具返回</summary><pre>{{JSON.stringify(run.value.result,null,2)}}</pre></details><button v-if="run.value.status==='prepared'" @click="reviewRun(run)">继续预览</button><button v-if="run.value.status==='persistence_failed'" @click="saveResult(run)">只重试保存</button><button v-if="['prepared','calling'].includes(run.value.status)" @click="stop(run)"><Square :size="16"/>停止</button></article><Sheet v-if="editor" title="MCP 连接" @close="closeEditor"><form class="final-card-form" @submit.prevent="save"><label>名称<input v-model="value.name" maxlength="200" required></label><label>Streamable HTTP 地址<input v-model="value.url" type="url" placeholder="https://example.com/mcp" required></label><label><KeyRound :size="16"/>Bearer 鉴权<input v-model="token" type="password" autocomplete="off" maxlength="16000"></label><label class="final-check"><input v-model="value.enabled" type="checkbox">启用连接</label><label>请求超时（毫秒）<input v-model.number="value.timeoutMs" type="number" min="100" max="120000"></label><label>每日工具调用上限<input v-model.number="value.dailyCalls" type="number" min="1" max="1000"></label><fieldset v-if="value.tools.length"><legend>允许使用的工具</legend><label v-for="item in value.tools" :key="item.name" class="final-check"><input v-model="value.allowedTools" :value="item.name" type="checkbox">{{item.title||item.name}}</label></fieldset><button class="final-primary" :disabled="busy">保存连接</button></form></Sheet><Sheet v-if="tool" :title="tool.title||tool.name" @close="closeTool"><p v-if="tool.description" class="final-subtle">{{tool.description}}</p><details><summary>参数格式</summary><pre>{{JSON.stringify(tool.inputSchema,null,2)}}</pre></details><form v-if="!invocation" class="final-card-form" @submit.prevent="preview"><label>工具参数<textarea v-model="args" aria-label="MCP 工具参数" class="final-code-input" maxlength="100000"></textarea></label><button class="final-primary" :disabled="busy">预览调用</button></form><div v-else class="final-card-form"><p>{{rows.find(row=>row.id===invocation!.value.connectorId)?.value.name||invocation.value.sourceUrl}} · {{invocation.value.tool.name}}</p><p class="final-subtle final-mcp-url">{{invocation.value.sourceUrl}}</p><pre>{{JSON.stringify(invocation.value.arguments,null,2)}}</pre><p class="final-subtle">参数将发送到此工具服务。外部写入以服务端结果为准。</p><button class="final-primary" :disabled="busy" @click="execute"><Check :size="18"/>确认调用一次</button></div></Sheet></section></template>
<style scoped>.final-mcp-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:24px}.final-mcp-grid .final-section-title,.final-mcp-run .final-section-title{margin:0}.final-mcp-url{overflow-wrap:anywhere}.final-mcp-tools{display:grid;gap:8px}.final-mcp-tools button{justify-content:start;text-align:left}.final-mcp-tools small{display:block;color:var(--quiet);font-size:12px}.final-mcp-run{margin-bottom:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;max-height:360px;overflow:auto}a{overflow-wrap:anywhere;color:var(--accent)}a svg{display:inline;vertical-align:middle;margin-right:6px}.final-setting-card{min-width:0}</style>
